<section class="card"><div class="section-head"><div><span class="eyebrow">02</span><h2>Carreras</h2></div><?php if($manage):?><a class="btn" href="<?=$u?>/admin/academico/carreras/form">Nueva carrera</a><?php endif;?></div><div class="table-scroll"><table><thead><tr><th>Código</th><th>Carrera</th><th>Tipo</th><th>Estado</th><th>Mallas</th><th></th></tr></thead><tbody><?php foreach($careers as $x):?><tr><td><code><?=htmlspecialchars($x['codigo'])?></code></td><td><strong><?=htmlspecialchars($x['nombre'])?></strong><br><small><?=htmlspecialchars($x['titulo_otorgado']?:'')?></small></td><td><?=htmlspecialchars($x['tipo']?:'—')?></td><td><?=htmlspecialchars($x['estado'])?><?=$x['permite_nuevos_ingresos']?' · admite ingresos':''?></td><td><?=$x['mallas']?></td><td><?php if($manage):?><a href="<?=$u?>/admin/academico/carreras/form?id=<?=$x['id']?>">Editar</a><?php endif;?></td></tr><?php endforeach;?><?php if(!$careers):?><tr><td colspan="6">No hay carreras registradas.</td></tr><?php endif;?></tbody></table></div></section>
<section class="card"><div class="section-head"><div><span class="eyebrow">03</span><h2>Mallas curriculares</h2></div><?php if($manage && $careers):?><a class="btn" href="<?=$u?>/admin/academico/mallas/form">Nueva malla</a><?php endif;?></div><div class="table-scroll"><table><thead><tr><th>Carrera</th><th>Código</th><th>Nombre / versión</th><th>Estado</th><th>Vigencia</th><th></th></tr></thead><tbody><?php foreach($curricula as $x):?><tr><td><?=htmlspecialchars($x['carrera'])?></td><td><code><?=htmlspecialchars($x['codigo'])?></code></td><td><?=htmlspecialchars($x['nombre'])?><?=($x['version']?' · '.htmlspecialchars($x['version']):'')?></td><td><?=htmlspecialchars($x['estado'])?><?=$x['permite_nuevos_estudiantes']?' · nuevos estudiantes':''?></td><td><?=htmlspecialchars($x['fecha_inicio_vigencia'])?> → <?=htmlspecialchars($x['fecha_fin_vigencia']?:'Actual')?></td><td><?php if($manage):?><a href="<?=$u?>/admin/academico/mallas/form?id=<?=$x['id']?>">Editar</a><?php endif;?></td></tr><?php endforeach;?><?php if(!$curricula):?><tr><td colspan="6">Todavía no hay mallas curriculares.</td></tr><?php endif;?></tbody></table></div></section>
